set.seed(4)
hits <- replicate(1000, {
  ci <- t.test(rnorm(10, 500, 6))$conf.int
  ci[1] <= 500 & 500 <= ci[2]
})
caught <- mean(hits)

kiosk <- data.frame(
  day = 1:12,
  temp = c(14, 16, 18, 20, 22, 24, 26, 28, 30, 19, 23, 27),
  sales = c(118, 152, 141, 196, 183, 240, 231, 292, 284, 170, 221, 248)
)
model <- lm(sales ~ temp, data = kiosk)
forecast <- function(t) {
  if (t < min(kiosk$temp) || t > max(kiosk$temp)) return(NA)
  round(unname(predict(model, newdata = data.frame(temp = t))))
}
